-- 0.16.0, T179: the contraction. The key writes and the first adds down the two-trip path write no 0.14 entry, and their change in 0.15's log is their record, which the audit pages and an offboarding report list where 0.14's `secret.write` and `member.add` stood (docs/design/two-trips.md, "As built: the contraction"), as they list the sign-ins (0042) and the token issues, revokes and sign-outs (0043). Indexes over those changes alone, each read newest first by `at`, then its number, every one, one member's, one environment's (the payload's `environmentId`, as the reads repeat it: change-records.ts, `recordField`), one key's: so a page reads as many index entries as it lists, however long the log grows (R48). Additive (AGENTS.md, "expand, then contract").
--> statement-breakpoint
CREATE INDEX "log_changes_written_idx" ON "log_changes" USING btree ("at","number") WHERE (strpos("log_changes"."payload", '{"digest":') = 1 AND strpos("log_changes"."payload", '"inputs":"') > 0);--> statement-breakpoint
CREATE INDEX "log_changes_written_actor_idx" ON "log_changes" USING btree ("actor","at","number") WHERE (strpos("log_changes"."payload", '{"digest":') = 1 AND strpos("log_changes"."payload", '"inputs":"') > 0);--> statement-breakpoint
CREATE INDEX "log_changes_written_environment_idx" ON "log_changes" USING btree (("payload"::jsonb ->> 'environmentId'),"at","number") WHERE (strpos("log_changes"."payload", '{"digest":') = 1 AND strpos("log_changes"."payload", '"inputs":"') > 0);--> statement-breakpoint
CREATE INDEX "log_changes_written_object_idx" ON "log_changes" USING btree ("object","at","number") WHERE (strpos("log_changes"."payload", '{"digest":') = 1 AND strpos("log_changes"."payload", '"inputs":"') > 0);--> statement-breakpoint
CREATE INDEX "log_changes_written_actor_environment_idx" ON "log_changes" USING btree ("actor",("payload"::jsonb ->> 'environmentId'),"at","number") WHERE (strpos("log_changes"."payload", '{"digest":') = 1 AND strpos("log_changes"."payload", '"inputs":"') > 0);--> statement-breakpoint
CREATE INDEX "log_changes_written_actor_object_idx" ON "log_changes" USING btree ("actor","object","at","number") WHERE (strpos("log_changes"."payload", '{"digest":') = 1 AND strpos("log_changes"."payload", '"inputs":"') > 0);--> statement-breakpoint
CREATE INDEX "log_changes_admitted_idx" ON "log_changes" USING btree ("at","number") WHERE (strpos("log_changes"."payload", '{"inputs":"') = 1 AND strpos("log_changes"."payload", '"op":"member.add"') > 0);--> statement-breakpoint
CREATE INDEX "log_changes_admitted_actor_idx" ON "log_changes" USING btree ("actor","at","number") WHERE (strpos("log_changes"."payload", '{"inputs":"') = 1 AND strpos("log_changes"."payload", '"op":"member.add"') > 0);--> statement-breakpoint
-- What share of the log each index's condition holds, which Postgres cannot guess for `strpos(…)` (it takes 0.5% for
-- `= 1`, a third for `> 0`): measured by ANALYZE, so that it estimates a key's writes as many as they are, and walks
-- `log_changes_written_object_idx` newest first for a page of them rather than reading every one to sort it (review r1
-- of #490: 3,680 pages for a key with 50,000 writes). Statistics, not a planner setting (R69).
CREATE STATISTICS "log_changes_records_stats" ON (strpos("payload", '{"digest":')), (strpos("payload", '"inputs":"')), (strpos("payload", '{"inputs":"')), (strpos("payload", '"op":"member.add"')) FROM "log_changes";
